return ["CREATE TABLE identity_confirmations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, identity_version INT UNSIGNED NOT NULL, action VARCHAR(32) CHARACTER SET ascii NOT NULL, payload_hash CHAR(64) CHARACTER SET ascii NOT NULL, state_hash CHAR(64) CHARACTER SET ascii NOT NULL, expires_at DATETIME(6) NOT NULL, consumed_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(actor_id) REFERENCES identity_users(id), FOREIGN KEY(session_id) REFERENCES identity_sessions(id), KEY ix_confirmations_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"];
